            <div class="text-center">
                <label class="form-label fw-semibold d-block">Avatar</label>
                <div class="mb-2">
                    @if (!string.IsNullOrWhiteSpace(avatarUrl))
                    {
                        <img src="@avatarUrl" alt="Avatar" class="rounded-circle border"
                             style="width:120px;height:120px;object-fit:cover;" />
                    }
                    else
                    {
                        <div class="rounded-circle bg-secondary d-inline-flex align-items-center justify-content-center"
                             style="width:120px;height:120px;">
                            <span class="text-white fs-1">👤</span>
                        </div>
                    }
                </div>
                <div class="mb-2">
                    <input type="text" class="form-control form-control-sm" placeholder="Avatar URL"
                           @bind="avatarUrl" />
                </div>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="SaveChanges" disabled="@isSaving">
            @(isSaving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@isSaving">
            Discard Changes
        </button>
    </div>
}

@code {
    private UserProfile? profile;
    private string displayName = "";
    private string email = "";
    private string bio = "";
    private string avatarUrl = "";

    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        isLoading = true;
        profile = await SettingsService.GetProfileAsync();
        PopulateFields(profile);
        isLoading = false;
    }

    private void PopulateFields(UserProfile p)
    {
        displayName = p.DisplayName;
        email = p.Email;
        bio = p.Bio;
        avatarUrl = p.AvatarUrl;
    }

    private async Task SaveChanges()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new UserProfile(displayName, email, avatarUrl, bio);
            await SettingsService.SaveProfileAsync(updated);
            profile = updated;
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (profile is not null)
        {
            PopulateFields(profile);
            statusMessage = null;
        }
    }
}
