        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = [.. prefs.MutedChannels];

        // Get all available channels from the service
        if (SettingsService is InMemorySettingsService inMemory)
        {
            allChannels = inMemory.GetAllChannels();
        }
        else
        {
            allChannels = [.. prefs.MutedChannels];
        }

        isLoading = false;
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var prefs = new NotificationPrefs(
                emailNotifications,
                pushNotifications,
                weeklyDigest,
                [.. mutedChannels]);
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            statusMessage = "Notification preferences saved!";
        }
        finally
        {
            isSaving = false;
        }
    }
}

