@* Security settings section *@

@using sv_5ce158679c8d4bc8a4e7f799f51cc7b9.Models
@inject ISettingsService SettingsService

<h4 class="mb-4">Security</h4>

@if (isLoading)
{
    <div class="text-center py-4">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (settings is not null)
{
    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <div class="card mb-3">
        <div class="card-header fw-semibold">Two-Factor Authentication</div>
        <div class="card-body d-flex align-items-center justify-content-between">
            <div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@twoFactorEnabled"
                           @onchange="Toggle2FA" />
                    <label class="form-check-label" for="twoFactor">
                        Enable Two-Factor Authentication
                    </label>
                </div>
                @if (settings.LastPasswordChange.HasValue)
                {
                    <small class="text-muted d-block mt-1">
                        Last password change: @settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                    </small>
                }
            </div>
            <span class="badge @(twoFactorEnabled ? "bg-success" : "bg-warning text-dark") fs-6">
                @(twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
    </div>

    <ActiveSessionsTable Sessions="sessions"
                         OnRevoke="HandleRevokeSession" />
}

@code {
    private SecuritySettings? settings;
    private List<ActiveSession>? sessions;
    private bool twoFactorEnabled;
    private bool isLoading = true;

    protected override async Task OnInitializedAsync()
    {
        await LoadSettings();
    }

    private async Task LoadSettings()
    {
        isLoading = true;
        settings = await SettingsService.GetSecuritySettingsAsync();
        sessions = settings.Sessions;
        twoFactorEnabled = settings.TwoFactorEnabled;
        isLoading = false;
    }

    private void Toggle2FA(ChangeEventArgs e)
    {
        twoFactorEnabled = (bool)(e.Value ?? false);
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        // Reload to update last password change date
        await LoadSettings();
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        await LoadSettings();
    }
}

