<div class="settings-dashboard d-flex gap-4">
    <div class="settings-sidebar">
        <SettingsSidebar ActiveSection="@activeSection"
                         OnSectionChanged="section => activeSection = section" />
    </div>
    <div class="settings-content flex-grow-1">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
