    min-width: 200px;
    max-width: 220px;
    border-right: 1px solid var(--bs-border-color);
    padding-right: 1rem;
}

.settings-content {
    min-width: 0;
}

::deep .nav-pills .nav-link {
    border-radius: 0.375rem;
    color: var(--bs-body-color);
    padding: 0.5rem 1rem;
